  let grid=[0,20,40,60,80].map(v=>'<line x1="48" y1="'+(plotH-(v/90*plotH)+16)+'" x2="'+w+'" y2="'+(plotH-(v/90*plotH)+16)+'" stroke="#d7dadd"/><text x="6" y="'+(plotH-(v/90*plotH)+20)+'" font-size="11" fill="#444">'+v+'</text>').join('');
