function planningBody(){let days=['Q 24','S 25','S 26','D 27','S 28','T 29','Q 30','Q 01','S 02','S 03','D 04','S 05','T 06','Q 07'];let rooms=['101 — Duplo','102 — Duplo','103 — Suite','104 — Familiar','201 — Vista mar','202 — Duplo','203 — Suite','204 — Vista mar','301 — Duplo','302 — Familiar','303 — Suite','304 — Duplo'];return `<div class="window-toolbar planning-toolbar"><label>De data: <input id="planDate" type="date" value="2026-09-28"></label><label>Noites: <input id="nights" type="number" min="1" max="60" value="14" style="width:55px"></label><label>Tipo: <select id="planTipo"><option>Quarto</option><option>Categoria</option></select></label><label>Nome: <input id="planSearch" placeholder=""></label><label>Categorias: <select><option>Hotel (Demo)</option></select></label><label class="plan-check"><input type="checkbox" checked> Agrupar por categoria</label><label>Quarto: <select><option>Sem quarto</option><option>Todos</option></select></label><label>Complexos: <select><option>Todos os complexos</option></select></label><label>Esquema de Cor: <select><option>Cor: Reserva</option></select></label><span class="spacer"></span><button class="toolbtn" data-action="plan-search">Pesquisar</button></div><div class="window-content planning-layout"><aside class="planning-side"><div class="planning-side-title">Pesquisa Avançada</div><div class="sidepanel"><div class="formrow"><label>Categoria</label><select><option>(Todas)</option><option>Duplo</option><option>Suite</option><option>Familiar</option><option>Vista mar</option></select></div><div class="formrow"><label>Estado</label><select><option>(Todos)</option><option>Ocupado</option><option>Livre</option><option>Manutenção</option></select></div><button class="toolbtn primary" data-action="plan-search">Pesquisar</button></div></aside><div class="occupancyboard"><div class="plan-month-label">set — 2026 / out — 2026 (demonstração)</div><table class="plan-grid"><thead><tr><th>Quarto</th>${days.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${rooms.map((room,i)=>`<tr><td>${room}</td>${days.map((d,j)=>{let booked=(i+j)%7===0||(i*2+j)%11===0;return `<td>${booked?`<div class="booking" title="Reserva de demonstração">DEMO — ${i+1}</div>`:((i+j)%8===0?'<span class="plan-livre">Livre</span>':'')}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></div><div class="window-bottom"><button class="actionbtn primary" data-action="new-res">Nova Reserva</button><button class="actionbtn" data-action="assign">Atribuir quarto</button><button class="actionbtn" data-action="maintenance">Manutenção</button><span class="grow"></span><span class="pager">Planning — PMS · mapa fictício · ${rooms.length} quartos</span><button class="bottom-close" data-close="Planning">Fechar</button></div>`}

function bindFilters(){const filter=()=>{let q=(($('#tableSearch')?.value||$('#statusSearch')?.value||$('#statusSearchDetail')?.value||'')).toLowerCase(),s=$('#quickStatus')?.value||$('#statusFilter')?.value||'',guest=$('#guestSearch')?.value.toLowerCase()||'',ref=$('#refSearch')?.value.toLowerCase()||'',start=$('#fromDate')?.value||'',end=$('#toDate')?.value||'',isRes=makeTable(active).res,shown=0;const iso=t=>{let a=t.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(a)return a[0];let b=t.match(/^(\d{2})[/-](\d{2})[/-](\d{4})$/);return b?`${b[3]}-${b[2]}-${b[1]}`:''};$('#rows')?.querySelectorAll('tr').forEach(tr=>{let text=tr.textContent.toLowerCase(),from=iso(tr.cells[4]?.textContent||''),to=iso(tr.cells[5]?.textContent||''),dateOk=!isRes||((!start||!from||from>=start)&&(!end||!to||to<=end)),ok=text.includes(q)&&text.includes(guest)&&text.includes(ref)&&(!s||text.toLowerCase().includes(s.toLowerCase()))&&dateOk;tr.hidden=!ok;if(ok)shown++});if($('#empty'))$('#empty').style.display=shown?'none':'block';if($('#pager'))$('#pager').textContent=`Página ${pageIndex+1} · ${shown} registos visíveis`};['#tableSearch','#quickStatus','#guestSearch','#refSearch','#statusSearch','#sideSearch','#statusFilter','#fromDate','#toDate'].forEach(sel=>{let el=$(sel);if(!el||el.dataset.bound)return;el.dataset.bound='1';el.addEventListener('input',e=>{if(e.target.id==='sideSearch'&&$('#tableSearch'))$('#tableSearch').value=e.target.value;filter()});el.addEventListener('change',filter)});let sort=$('#sortBy');if(sort&&!sort.dataset.bound){sort.dataset.bound='1';sort.addEventListener('change',e=>{let tbody=$('#rows');if(!tbody)return;let rows=[...tbody.querySelectorAll('tr')],col=e.target.value==='name'?1:e.target.value==='id'?0:4;rows.sort((a,b)=>a.cells[col].textContent.localeCompare(b.cells[col].textContent));if(!sortAsc)rows.reverse();sortAsc=!sortAsc;rows.forEach(r=>tbody.appendChild(r))})}}
function showModal(title,fields,submitLabel='Guardar'){let html=fields.map(f=>`<div class="field ${f.full?'full':''}"><label>${esc(f.label)}</label>${f.options?`<select name="${esc(f.name)}">${f.options.map(o=>`<option>${esc(o)}</option>`).join('')}</select>`:`<input name="${esc(f.name)}" type="${f.type||'text'}" ${f.value?`value="${esc(f.value)}"`:''} ${f.required?'required':''} placeholder="${esc(f.placeholder||'')}">`}</div>`).join('');$('#overlay').innerHTML=`<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true"><header class="modal-head">${esc(title)} <button data-modal-close aria-label="Fechar">×</button></header><form id="modalForm"><div class="modal-body"><div class="formgrid">${html}</div><p class="formnote">Simulação local isolada do Host PMS. Os dados introduzidos ficam apenas neste navegador.</p></div><footer class="modal-foot"><button type="button" class="toolbtn" data-modal-close>Fechar</button><button class="toolbtn primary" type="submit">${esc(submitLabel)}</button></footer></form></section></div>`}
