function reportControl(p,i){let id=`rparam-${i}`;if(p.type==='date')return `<input id="${id}" type="date" value="2026-09-26">`;if(p.type==='text'||p.type==='number')return `<input id="${id}" type="${p.type}" placeholder="${p.type==='text'?'Pesquisar…':''}">`;return `<select id="${id}">${p.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`}
function reportDemoRows(){return [['RPT-DEMO-001','DEMO-101','Hóspede Fictício A','Duplo','26-09-2026','Demonstração','120,00 EUR'],['RPT-DEMO-002','DEMO-204','Hóspede Fictício B','Suite','27-09-2026','Demonstração','185,00 EUR'],['RPT-DEMO-003','DEMO-310','Hóspede Fictício C','Familiar','28-09-2026','Demonstração','240,00 EUR']]}
function reportsBody(){
  let current=reportCatalog.find(x=>x.id===reportCurrent),query=reportSearchQuery.toLowerCase();
  let crumbHtml=`<button type="button" class="report-crumb" data-report-home>Start Page</button>${reportFolder?`<span class="report-crumb-sep"> &gt; </span><button type="button" class="report-crumb" data-report-folder-crumb="${esc(reportFolder)}">${esc(reportFolder)}</button>`:''}${current?`<span class="report-crumb-sep"> &gt; </span><span class="report-crumb-current">${esc(current.name)}</span>`:''}`;
  let topline=`<div class="report-topline"><div class="report-topline-row"><div class="report-crumb-wrap">${crumbHtml}</div><label class="report-searchbox"><input id="reportSearch" value="${esc(reportSearchQuery)}" placeholder=""><button type="button" class="report-search-btn" title="Search" data-report-search-ico>Search ▾</button><button type="button" data-report-clear title="Limpar">×</button></label></div><div class="report-topline-row report-topline-opts"><label class="report-open-new"><input type="checkbox" id="reportOpenNew"> Open new window</label></div></div>`;
  let fecharBar=`<footer class="report-catalog-footer"><span class="report-footer-tab">Relatórios</span><span class="report-footer-meta">${reportCatalog.length} relatórios · ${reportFolders.length} pastas · dados fictícios</span><button type="button" class="report-fechar host-btn-fechar" data-close-window><span class="report-fechar-ico" aria-hidden="true">×</span><span>Fechar</span></button></footer>`;
  if(current){
    let params=reportParameters(current),rows=reportDemoRows();
    return `<section class="reports-window"><header class="reports-title">Relatórios</header>${topline}<div class="report-viewer-scroll"><section class="ssrs-params"><div class="ssrs-param-grid">${params.map((p,i)=>`<label class="ssrs-param"><span>${esc(p.label)}:</span>${reportControl(p,i)}</label>`).join('')}</div><div class="ssrs-run"><button type="button" class="ssrs-exibir" data-report-run>Exibir Relatório</button></div></section><div class="ssrs-report-toolbar"><button type="button" disabled title="Primeira">|&lt;</button><button type="button" disabled title="Anterior">&lt;</button><span class="ssrs-page">${reportPreview?'1 de 1':'0 de 0'}</span><button type="button" disabled title="Seguinte">&gt;</button><button type="button" disabled title="Última">&gt;|</button><button type="button" data-report-run title="Atualizar">⟳</button><button type="button" data-report-back title="Voltar parâmetros">↩</button><label class="ssrs-zoom">Zoom <select><option>100%</option><option>75%</option><option>50%</option><option>Página Inteira</option></select></label><span class="spacer"></span><button type="button" data-report-export title="Exportar">Exportar ▾</button><button type="button" data-report-print title="Imprimir">Imprimir</button><input class="ssrs-find" placeholder="Localizar" title="Localizar"></div>${reportPreview?`<div class="ssrs-paper"><h2>${esc(current.name)}</h2><p class="ssrs-meta">28/09/2026 · Hotel de demonstração · pré-visualização fictícia</p><table class="grid"><thead><tr><th>Referência</th><th>Quarto</th><th>Hóspede (demo)</th><th>Tipologia</th><th>Data</th><th>Estado</th><th>Valor demo</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="ssrs-demo-note">Aperçu local fictif — aucune donnée nominative du PMS.</p></div>`:`<div class="ssrs-empty-preview"><div class="ssrs-loading-hint">Defina os parâmetros e clique em « Exibir Relatório ».<br><small>Pré-visualização local apenas com dados fictícios.</small></div></div>`}</div>${fecharBar}</section>`;
  }
  if(!reportFolder){
    let folders=reportFolders.filter(f=>!query||`${f.name} ${f.items.join(' ')}`.toLowerCase().includes(query));
    let found=query?reportCatalog.filter(r=>`${r.name} ${r.folder}`.toLowerCase().includes(query)):[];
    return `<section class="reports-window"><header class="reports-title">Relatórios</header>${topline}<div class="report-browser-scroll"><div class="report-folder-grid">${folders.map(f=>`<button type="button" class="report-folder-tile" data-report-folder="${esc(f.name)}"><span class="report-folder-icon" aria-hidden="true"></span><span class="report-folder-name">${esc(f.name)}</span></button>`).join('')}</div>${query?`<h3 class="report-search-heading">Resultados · ${found.length}</h3><div class="report-file-grid">${found.map(r=>`<button type="button" class="report-result" data-report-open="${esc(r.id)}"><span class="report-file-icon" aria-hidden="true"></span><span class="report-file-name">${esc(r.name)}<small>${esc(r.folder)}</small></span></button>`).join('')}</div>`:''}</div>${fecharBar}</section>`;
  }
  let results=reportCatalog.filter(r=>r.folder===reportFolder&&(!query||r.name.toLowerCase().includes(query)));
  return `<section class="reports-window"><header class="reports-title">Relatórios</header>${topline}<div class="report-browser-scroll"><div class="report-file-grid">${results.map(r=>`<button type="button" class="report-result" data-report-open="${esc(r.id)}"><span class="report-file-icon" aria-hidden="true"></span><span class="report-file-name">${esc(r.name)}</span></button>`).join('')||'<p class="report-empty">Nenhum ficheiro neste dossier.</p>'}</div></div>${fecharBar}</section>`;
}
const genericModuleBody=moduleBody;moduleBody=function(page){return page==='Relatórios'?reportsBody():genericModuleBody(page)};
document.addEventListener('input',e=>{if(e.target.id==='reportSearch'){reportSearchQuery=e.target.value;let q=reportSearchQuery.toLowerCase();document.querySelectorAll('.report-folder-tile').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q));document.querySelectorAll('.report-result').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))}});
document.addEventListener('click',e=>{let f=e.target.closest('[data-report-folder]'),r=e.target.closest('[data-report-open]');if(f){reportFolder=f.dataset.reportFolder;reportCurrent=null;reportSearchQuery='';renderAll()}else if(r){document.querySelectorAll(".report-result.is-selected").forEach(x=>x.classList.remove("is-selected"));r.classList.add("is-selected");reportCurrent=r.dataset.reportOpen;reportPreview=false;renderAll()}else if(e.target.closest('[data-report-folder-crumb]')){reportCurrent=null;reportPreview=false;reportFolder=e.target.closest('[data-report-folder-crumb]').dataset.reportFolderCrumb;renderAll()}else if(e.target.closest('[data-report-home]')){if(reportCurrent){reportCurrent=null;reportPreview=false}else reportFolder='';renderAll()}else if(e.target.closest('[data-report-clear]')){reportSearchQuery='';renderAll()}else if(e.target.closest('[data-report-back]')){let p=document.querySelector('.ssrs-param-grid');if(p)p.hidden=!p.hidden}else if(e.target.closest('[data-report-run]')){reportPreview=true;renderAll()}else if(e.target.closest('[data-report-export]')){let rows=reportDemoRows(),csv=['Referência;Quarto;Hóspede demo;Tipologia;Data;Estado;Valor demo',...rows.map(x=>x.join(';'))].join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='relatorio-demonstracao.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV fictício exportado.')}else if(e.target.closest('[data-report-print]'))toast('Impressão disponible après la pré-visualisation fictive.')});
init();







